//! [`PrefabInstance`]: a saved component that instances a scene asset, and
//! [`Instanced`]: the runtime marker on the entities it instantiates.
//!
//! The instancing itself (loading the scene asset, spawning its entities,
//! following hot reloads) is done by `box_engine`'s asset glue. What lives
//! here is the data every crate needs to treat instanced entities as
//! runtime-only: scene saving skips them, `box_core::edit` refuses to edit
//! them or to place entities under them, and the editor can show them as
//! read-only.
//!
//! Entities generated by rules ([`Derived`](crate::derived::Derived)) share
//! all of this. Code that treats runtime-only entities specially tests
//! [`is_generated`] (or filters queries with [`NotGenerated`]), never one
//! marker alone.

use crate::asset_ref::AssetRef;
use crate::derived::{Derived, Preview};
use crate::identity::Uid;
use crate::reflect::{Reflect, ReflectComponent, ReflectDefault};
use crate::world::{Entity, World};

/// Instances a scene asset (a `.scene.json`/`.prefab.json` file, or a glTF's
/// `#Scene`) beneath this entity. Only this component, the entity's own
/// `Name` and `Transform` are saved; the instanced contents are runtime
/// entities, instantiated by the asset glue, never saved, and rebuilt when
/// the source scene changes. No per-instance overrides yet (M4).
#[derive(Clone, Debug, Default, PartialEq, Reflect)]
#[reflect(Component, Default, Clone, Debug, PartialEq)]
#[type_path = "box_engine"]
pub struct PrefabInstance {
    /// The scene to instance, such as `models/tower.glb#Scene` or
    /// `prefabs/lamp.scene.json`.
    pub scene: AssetRef,
}

/// Runtime marker on every entity instantiated from a [`PrefabInstance`]
/// (at any nesting depth). Not registered, so never saved; entities that
/// carry it are skipped by `scene::save` and `scene::save_subtree` (their
/// saved descendants, if any, are written under the nearest saved
/// ancestor) and refused by `box_core::edit` (editing them, or spawning,
/// pasting or reparenting under them). Edit the instance root's
/// `PrefabInstance`, `Name` or `Transform` instead: the contents are rebuilt
/// from the source scene.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Instanced {
    /// The entity with the `PrefabInstance` that spawned this one (for a
    /// nested prefab, the nested instance entity, itself instanced).
    pub instance: Entity,
    /// 1 for the contents of a saved instance, 2 for the contents of a
    /// prefab nested in it, and so on (at most [`MAX_PREFAB_DEPTH`]).
    pub depth: u32,
}

/// Prefabs may nest this deep; deeper instances are refused with an error
/// (and a prefab that contains itself, directly or not, is refused at once).
pub const MAX_PREFAB_DEPTH: u32 = 8;

/// True when `e` was instantiated from a prefab (it has [`Instanced`]).
/// Most code wants [`is_generated`], which also covers derived entities.
pub fn is_instanced(world: &World, e: Entity) -> bool {
    world.has::<Instanced>(e)
}

/// True when `e` is runtime-only generated content: instantiated from a
/// prefab ([`Instanced`]), produced by a rule
/// ([`Derived`](crate::derived::Derived)) or an editor tool's preview
/// ([`Preview`](crate::derived::Preview)). Such entities are never saved,
/// never edited through `box_core::edit`, hidden in the hierarchy, and a
/// click on one selects its [`editable_ancestor`].
pub fn is_generated(world: &World, e: Entity) -> bool {
    world.has::<Instanced>(e) || world.has::<Derived>(e) || world.has::<Preview>(e)
}

/// Query filter matching generated entities (any marker).
pub type AnyGenerated = hecs::Or<&'static Instanced, hecs::Or<&'static Derived, &'static Preview>>;

/// `Q` without generated entities: `world.query::<NotGenerated<(Entity,
/// &Uid)>>()` lists the saved, editable entities.
pub type NotGenerated<Q> = crate::world::Without<Q, AnyGenerated>;

/// The nearest ancestor-or-self of `e` that is not generated: what the
/// editor selects, picks and edits when the user clicks generated content
/// (the outermost saved `PrefabInstance` root, or the owner of a derived
/// part). A derived part without a parent goes to its recorded owner.
pub fn editable_ancestor(world: &World, e: Entity) -> Entity {
    let mut cur = e;
    // Bounded: a malformed owner chain must not loop forever.
    for _ in 0..1024 {
        if !is_generated(world, cur) {
            break;
        }
        let next = world
            .parent(cur)
            .or_else(|| world.get::<Derived>(cur).map(|d| d.owner))
            .filter(|n| world.contains(*n));
        match next {
            Some(p) => cur = p,
            None => break,
        }
    }
    cur
}

/// The uid of the entity with prefab-local uid `local` inside the instance
/// whose root has uid `instance`: deterministic, so instanced entities keep
/// their uids when the source scene is reloaded or the scene is loaded
/// again (selection and references by uid stay valid), and distinct for
/// every instance of the same prefab.
pub fn instanced_uid(instance: Uid, local: Uid) -> Uid {
    fn mix(mut z: u64) -> u64 {
        z = z.wrapping_add(0x9E37_79B9_7F4A_7C15);
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }
    let (a, b) = (instance.0.as_u128(), local.0.as_u128());
    let hi = mix(a as u64 ^ mix(b as u64 ^ mix((b >> 64) as u64)));
    let lo = mix((a >> 64) as u64 ^ hi.rotate_left(23) ^ mix(b as u64).rotate_left(7));
    let bytes = ((u128::from(hi) << 64) | u128::from(lo)).to_le_bytes();
    Uid(uuid::Builder::from_random_bytes(bytes).into_uuid())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::reflect::Registry;

    #[test]
    fn round_trips_and_accepts_a_path_string() {
        let registry = Registry::with_core_types();
        let p = PrefabInstance {
            scene: AssetRef::path("models/tower.glb#Scene"),
        };
        let json = registry.value_to_json(&p).unwrap();
        assert_eq!(
            json,
            serde_json::json!({"scene": {"label": "Scene", "path": "models/tower.glb"}})
        );
        let ty = registry.component("PrefabInstance").unwrap();
        let short = serde_json::json!({"scene": "prefabs/lamp.scene.json"});
        let back = registry.value_from_json(ty.type_id(), &short).unwrap();
        let back =
            <PrefabInstance as bevy_reflect::FromReflect>::from_reflect(back.as_ref()).unwrap();
        assert_eq!(back.scene.path.as_deref(), Some("prefabs/lamp.scene.json"));
        assert!(registry.value_from_json(ty.type_id(), &json).is_ok());
    }

    #[test]
    fn instanced_uids_are_deterministic_and_distinct() {
        let (a, b) = (Uid::from_u128(1), Uid::from_u128(2));
        let local = Uid::from_u128(3);
        assert_eq!(instanced_uid(a, local), instanced_uid(a, local));
        assert_ne!(instanced_uid(a, local), instanced_uid(b, local));
        assert_ne!(instanced_uid(a, local), instanced_uid(a, Uid::from_u128(4)));
        assert_ne!(instanced_uid(a, local), local);
    }

    #[test]
    fn editable_ancestor_skips_instanced_entities() {
        let mut w = World::new();
        let root = w.spawn((Uid::new(),));
        let child = w.spawn((Uid::new(),));
        let leaf = w.spawn((Uid::new(),));
        w.set_parent(child, Some(root)).unwrap();
        w.set_parent(leaf, Some(child)).unwrap();
        let marker = Instanced {
            instance: root,
            depth: 1,
        };
        w.insert_one(child, marker).unwrap();
        w.insert_one(leaf, marker).unwrap();
        assert_eq!(editable_ancestor(&w, leaf), root);
        assert_eq!(editable_ancestor(&w, root), root);
        assert!(is_instanced(&w, leaf) && !is_instanced(&w, root));
        assert!(is_generated(&w, leaf) && !is_generated(&w, root));
    }

    #[test]
    fn derived_entities_are_generated_and_map_to_their_owner() {
        use crate::derived::PartKey;
        let mut w = World::new();
        let owner_uid = Uid::new();
        let owner = w.spawn((owner_uid,));
        let key = PartKey::new(owner_uid, "wall");
        let marker = Derived {
            owner,
            key: key.clone(),
            rule: "walls".into(),
        };
        let part = w.spawn((key.uid(), marker.clone()));
        w.set_parent(part, Some(owner)).unwrap();
        // A prefab instanced under a derived part: both markers chain.
        let inner = w.spawn((
            Uid::new(),
            Instanced {
                instance: part,
                depth: 1,
            },
        ));
        w.set_parent(inner, Some(part)).unwrap();
        assert!(is_generated(&w, part) && !is_instanced(&w, part));
        assert_eq!(editable_ancestor(&w, part), owner);
        assert_eq!(editable_ancestor(&w, inner), owner);
        // Without a parent the recorded owner is used.
        let loose = w.spawn((Uid::new(), marker));
        assert_eq!(editable_ancestor(&w, loose), owner);
        // Queries skip both markers.
        let listed: Vec<Entity> = w
            .query::<NotGenerated<(Entity, &Uid)>>()
            .iter()
            .map(|(e, _)| e)
            .collect();
        assert_eq!(listed, vec![owner]);
    }
}
